1	import { rulesPresets, type RulesPresetId } from "@pirate-sea-race/content";
2	import {
3	  objectiveRules,
4	  presetRubbings,
5	  presetRubbingTypes,
6	  rubbingTypeOrder,
7	  sourceId,
8	  validateObjectiveRules,
9	  validateSourceAssignment,
10	  validateSourceSites,
11	  validateSupplyCaches,
12	  type GoldGrantReason,
13	  type ObjectiveRules,
14	  type RubbingType,
15	  type ShopItem,
16	  type SourceAssignment,
17	  type SourceSite,
18	} from "@pirate-sea-race/content/objectives";
19	import { nextInt } from "../random.js";
20	
21	/** An integer sub-unit position supplied by the caller; the ledger does not know the map. */
22	export interface Position {
23	  readonly x: number;
24	  readonly y: number;
25	}
26	
27	/**
28	 * The one place a rubbing is (§4): sealed at its source, owned by a player, held in a recovery cache, or reserved for
29	 * one of the two players inside an unresolved duel.
30	 */
31	export type RubbingLocation =
32	  | { readonly kind: "source"; readonly sourceId: string }
33	  | { readonly kind: "player"; readonly playerId: string }
34	  | { readonly kind: "cache"; readonly cacheId: string }
35	  | { readonly kind: "duel"; readonly duelId: string; readonly playerId: string };
36	
37	/** §16's rubbing: its id and type never change; `revision` counts the moves it has made. */
38	export interface LedgerRubbing {
39	  readonly id: string;
40	  readonly type: RubbingType;
41	  readonly location: RubbingLocation;
42	  readonly revision: number;
43	}
44	
45	/** A source and the rubbing sealed there at the start. It is empty once that rubbing has left; nothing respawns. */
46	export interface LedgerSource {
47	  readonly id: string;
48	  readonly island: number;
49	  readonly x: number;
50	  readonly y: number;
51	  readonly type: RubbingType;
52	  readonly rubbingId: string;
53	  /** Sources start locked; the ruin that guards one unlocks it. */
54	  readonly unlocked: boolean;
55	}
56	
57	/** A held interaction: `heldTicks` counts consecutive ticks of holding since `startTick`. */
58	export type LedgerChannel =
59	  | {
60	      readonly kind: "collect";
61	      readonly sourceId: string;
62	      readonly rubbingId: string;
63	      readonly startTick: number;
64	      readonly lastTick: number;
65	      readonly heldTicks: number;
66	    }
67	  | {
68	      readonly kind: "claim";
69	      readonly cacheId: string;
70	      readonly rubbingId: string;
71	      readonly startTick: number;
72	      readonly lastTick: number;
73	      readonly heldTicks: number;
74	    };
75	
76	export type PlayerStatus = "connected" | "disconnected" | "left";
77	
78	export interface LedgerPlayer {
79	  readonly id: string;
80	  readonly gold: number;
81	  readonly status: PlayerStatus;
82	  /** While disconnected: the tick at which the seat reservation expires. Reconnecting never moves it. */
83	  readonly reservationDeadline: number | null;
84	  /** Once left: where rubbings still reserved in an unresolved duel go when that duel settles. */
85	  readonly exit: Position | null;
86	  readonly channel: LedgerChannel | null;
87	  /** Types this player lost and is owed a fresh rumor for (§11), in type order. The rumor system reads it. */
88	  readonly freshRumors: readonly RubbingType[];
89	  /** Sail tonics carried (§11): 0 up to the rules' carry limit. A lost duel keeps them; leaving drops them. */
90	  readonly tonics: number;
91	  /** The last tonic activated, if any; it is active from `startTick` until just before `endTick`. */
92	  readonly tonicEffect: TonicEffect | null;
93	}
94	
95	/** An activated sail tonic: active on the ticks `startTick ≤ tick < endTick`, `endTick = startTick + tonicTicks`. */
96	export interface TonicEffect {
97	  readonly startTick: number;
98	  readonly endTick: number;
99	}
100	
101	/**
102	 * Gold the rules minted (§11). Its key makes it once only: a `ruin` grant once per (player, `sourceKey`), a
103	 * `supply-cache` grant once per `sourceKey` for the whole match. The key is bounded by what the ledger knows: a ruin's
104	 * key is `String(island)` for one of its sources' islands (the ruins module's key), a supply cache's is one of
105	 * `supplyCaches`.
106	 */
107	export interface GoldGrant {
108	  readonly reason: GoldGrantReason;
109	  readonly sourceKey: string;
110	  readonly playerId: string;
111	  readonly amount: number;
112	  readonly tick: number;
113	}
114	
115	/** A completed dockside purchase, kept under (player, request id) so a retry finds it instead of paying again (§11, §16). */
116	export interface PurchaseRecord {
117	  readonly kind: "purchase";
118	  readonly requestId: string;
119	  readonly playerId: string;
120	  readonly item: ShopItem;
121	  readonly price: number;
122	  readonly tick: number;
123	  /** The buyer's gold and tonics right after the purchase. */
124	  readonly goldAfter: number;
125	  readonly tonicsAfter: number;
126	}
127	
128	/** The refusals that are decisions on a well-formed request from a player in the match, and so are kept (§16). */
129	export const RECORDED_REFUSALS = ["insufficient-gold", "tonic-limit", "player-in-duel", "player-disconnected"] as const;
130	export type RecordedRefusal = (typeof RECORDED_REFUSALS)[number];
131	
132	/** At most this many refusals are kept per player; the oldest goes first, and its id is then evaluated afresh. */
133	export const MAX_RECORDED_REFUSALS = 16;
134	
135	/** A decided refusal, kept under (player, request id) so a retry gets the same answer even if it would succeed now. */
136	export interface RefusalRecord {
137	  readonly kind: "refusal";
138	  readonly requestId: string;
139	  readonly playerId: string;
140	  readonly item: ShopItem;
141	  readonly tick: number;
142	  readonly rejection: RecordedRefusal;
143	}
144	
145	/** The outcome of a purchase request, kept under its (player, request id). */
146	export type PurchaseOutcome = PurchaseRecord | RefusalRecord;
147	
148	/** A recovery cache (§12). It never despawns; it disappears once empty. Its contents are the rubbings located in it. */
149	export interface LedgerCache {
150	  readonly id: string;
151	  readonly x: number;
152	  readonly y: number;
153	  readonly createdTick: number;
154	}
155	
156	/** `fighting` until the result arrives; `choosing` while the winner picks a type; `settled` once committed. */
157	export type DuelPhase = "fighting" | "choosing" | "settled";
158	
159	export interface DuelResultRecord {
160	  readonly outcome: "win" | "draw" | "cancelled";
161	  readonly winner: string | null;
162	  readonly loser: string | null;
163	  /** Decided by leaving the match (quit or reservation expiry) during the fight: the loser for a win, both players for a cancellation. */
164	  readonly forfeit: boolean;
165	  readonly tick: number;
166	}
167	
168	/** What the commit did. It happens once per duel. */
169	export interface DuelSettlement {
170	  readonly tick: number;
171	  readonly stolenRubbingId: string | null;
172	  readonly stolenType: RubbingType | null;
173	  /** Who picked the stolen type: the winner, the default at the deadline, or nobody (nothing moved). */
174	  readonly choice: "winner" | "default" | "none";
175	  readonly gold: number;
176	  readonly goldSuppressed: boolean;
177	}
178	
179	export interface LedgerDuel {
180	  readonly id: string;
181	  readonly players: readonly [string, string];
182	  readonly startTick: number;
183	  readonly phase: DuelPhase;
184	  readonly result: DuelResultRecord | null;
185	  /** In `choosing`: the first tick at which the winner can no longer choose and the default applies. */
186	  readonly choiceDeadline: number | null;
187	  readonly settlement: DuelSettlement | null;
188	}
189	
190	/** The last win of `winner` over `loser`, for §11's repeated-victory gold suppression. */
191	export interface WinRecord {
192	  readonly winner: string;
193	  readonly loser: string;
194	  readonly tick: number;
195	}
196	
197	/** The whole ledger: plain, integer data that `hashState` covers entirely. */
198	export interface LedgerState {
199	  readonly preset: RulesPresetId;
200	  readonly rules: ObjectiveRules;
201	  /** The preset's types, in the fixed type order. */
202	  readonly types: readonly RubbingType[];
203	  /** The latest world tick an applied request carried. Requests from earlier ticks are stale. */
204	  readonly tick: number;
205	  readonly rng: number;
206	  readonly sources: readonly LedgerSource[];
207	  /** Every rubbing of the preset, by id. */
208	  readonly rubbings: readonly LedgerRubbing[];
209	  /** In join order; a player who left stays, with status `left`. */
210	  readonly players: readonly LedgerPlayer[];
211	  readonly caches: readonly LedgerCache[];
212	  /** In reservation order, settled ones included, so a repeated message finds its result. */
213	  readonly duels: readonly LedgerDuel[];
214	  readonly wins: readonly WinRecord[];
215	  readonly nextCacheNumber: number;
216	  /**
217	   * Gold players brought in when joining (the rules' `startingGold` each) plus the gold grants minted. Settlements
218	   * only move gold and purchases spend it, so the balances plus `goldSpent` always sum to this.
219	   */
220	  readonly goldIssued: number;
221	  /** Gold spent at the shop: it leaves the balances and goes to nobody. */
222	  readonly goldSpent: number;
223	  /** The supply caches of this match, by id, given at creation: the only keys a `supply-cache` grant may carry. */
224	  readonly supplyCaches: readonly string[];
225	  /** Every grant made, in order. */
226	  readonly grants: readonly GoldGrant[];
227	  /**
228	   * Every purchase and every kept refusal, in order; (player, request id) is unique. Purchases are never dropped;
229	   * each player's refusals beyond `MAX_RECORDED_REFUSALS` are, oldest first.
230	   */
231	  readonly requests: readonly PurchaseOutcome[];
232	}
233	
234	/**
235	 * Deals the preset's rubbings onto the sites with the seeded generator: a Fisher–Yates shuffle, so the server alone
236	 * decides, and the same seed and sites always give the same assignment. Source ids number each island's sites in the
237	 * order given.
238	 */
239	export function assignSources(
240	  presetId: RulesPresetId,
241	  sites: readonly SourceSite[],
242	  seed: number,
243	): { assignment: SourceAssignment; rng: number } {
244	  if (!Number.isInteger(seed)) throw new RangeError(`seed must be an integer, got ${seed}`);
245	  const preset = rulesPresets[presetId];
246	  const checked = validateSourceSites(preset, sites);
247	  if (!checked.ok) throw new Error(`invalid source sites for ${presetId}: ${checked.issues.join("; ")}`);
248	  const deck = presetRubbings(preset);
249	  let rng = seed >>> 0;
250	  for (let index = deck.length - 1; index > 0; index--) {
251	    const drawn = nextInt(rng, index + 1);
252	    rng = drawn.state;
253	    [deck[index], deck[drawn.value]] = [deck[drawn.value]!, deck[index]!];
254	  }
255	  const slots = new Map<number, number>();
256	  const sources = checked.value.map((site, index) => {
257	    const slot = slots.get(site.island) ?? 0;
258	    slots.set(site.island, slot + 1);
259	    const rubbing = deck[index]!;
260	    return { id: sourceId(site.island, slot), island: site.island, x: site.x, y: site.y, type: rubbing.type, rubbingId: rubbing.id };
261	  });
262	  const assignment = validateSourceAssignment({ preset: presetId, seed: seed >>> 0, sources });
263	  if (!assignment.ok) throw new Error(`invalid source assignment: ${assignment.issues.join("; ")}`);
264	  return { assignment: assignment.value, rng };
265	}
266	
267	export interface CreateLedgerOptions {
268	  readonly preset: RulesPresetId;
269	  readonly seed: number;
270	  readonly sites: readonly SourceSite[];
271	  readonly rules?: ObjectiveRules;
272	  /** The match's supply-cache ids; none means no supply-cache grants. */
273	  readonly supplyCaches?: readonly string[];
274	}
275	
276	/** A new match's ledger: every rubbing sealed at its (locked) source, no players, caches or duels. */
277	export function createLedger(options: CreateLedgerOptions): LedgerState {
278	  const rules = validateObjectiveRules(options.rules ?? objectiveRules);
279	  if (!rules.ok) throw new Error(`invalid objective rules: ${rules.issues.join("; ")}`);
280	  const { assignment, rng } = assignSources(options.preset, options.sites, options.seed);
281	  return createLedgerFromAssignment(assignment, rng, rules.value, options.supplyCaches);
282	}
283	
284	/** A ledger from an assignment made earlier (validated again here), for example one restored from a match record. */
285	export function createLedgerFromAssignment(
286	  candidate: SourceAssignment,
287	  rng: number,
288	  rules: ObjectiveRules = objectiveRules,
289	  supplyCaches: readonly string[] = [],
290	): LedgerState {
291	  const parsed = validateSourceAssignment(candidate);
292	  if (!parsed.ok) throw new Error(`invalid source assignment: ${parsed.issues.join("; ")}`);
293	  const checkedRules = validateObjectiveRules(rules);
294	  if (!checkedRules.ok) throw new Error(`invalid objective rules: ${checkedRules.issues.join("; ")}`);
295	  const cacheIds = validateSupplyCaches(supplyCaches);
296	  if (!cacheIds.ok) throw new Error(`invalid supply caches: ${cacheIds.issues.join("; ")}`);
297	  const assignment = parsed.value;
298	  const sources: LedgerSource[] = assignment.sources.map((source) => ({ ...source, unlocked: false }));
299	  const rubbings: LedgerRubbing[] = sources
300	    .map((source) => ({
301	      id: source.rubbingId,
302	      type: source.type,
303	      location: { kind: "source", sourceId: source.id } as const,
304	      revision: 0,
305	    }))
306	    .sort(byId);
307	  return {
308	    preset: assignment.preset,
309	    rules: checkedRules.value,
310	    types: presetRubbingTypes(rulesPresets[assignment.preset]),
311	    tick: 0,
312	    rng: rng >>> 0,
313	    sources,
314	    rubbings,
315	    players: [],
316	    caches: [],
317	    duels: [],
318	    wins: [],
319	    nextCacheNumber: 1,
320	    goldIssued: 0,
321	    goldSpent: 0,
322	    supplyCaches: cacheIds.value,
323	    grants: [],
324	    requests: [],
325	  };
326	}
327	
328	export function byId<T extends { readonly id: string }>(a: T, b: T): number {
329	  return a.id < b.id ? -1 : a.id > b.id ? 1 : 0;
330	}
331	
332	export function byTypeOrder(a: RubbingType, b: RubbingType): number {
333	  return rubbingTypeOrder(a) - rubbingTypeOrder(b);
334	}
335	
336	export function findPlayer(state: LedgerState, id: string): LedgerPlayer | undefined {
337	  return state.players.find((player) => player.id === id);
338	}
339	
340	export function findSource(state: LedgerState, id: string): LedgerSource | undefined {
341	  return state.sources.find((source) => source.id === id);
342	}
343	
344	export function findCache(state: LedgerState, id: string): LedgerCache | undefined {
345	  return state.caches.find((cache) => cache.id === id);
346	}
347	
348	export function findDuel(state: LedgerState, id: string): LedgerDuel | undefined {
349	  return state.duels.find((duel) => duel.id === id);
350	}
351	
352	export function findRubbing(state: LedgerState, id: string): LedgerRubbing | undefined {
353	  return state.rubbings.find((rubbing) => rubbing.id === id);
354	}
355	
356	/** A player's rubbings: those they own and those reserved for them in an unresolved duel. */
357	export function heldRubbings(state: LedgerState, playerId: string): LedgerRubbing[] {
358	  return state.rubbings.filter(
359	    (rubbing) =>
360	      (rubbing.location.kind === "player" || rubbing.location.kind === "duel") && rubbing.location.playerId === playerId,
361	  );
362	}
363	
364	export function heldTypes(state: LedgerState, playerId: string): RubbingType[] {
365	  return heldRubbings(state, playerId)
366	    .map((rubbing) => rubbing.type)
367	    .sort(byTypeOrder);
368	}
369	
370	/** The input §5's claim rules take: the player holds every type of the preset. */
371	export function holdsAllTypes(state: LedgerState, playerId: string): boolean {
372	  const held = new Set(heldTypes(state, playerId));
373	  return state.types.every((type) => held.has(type));
374	}
375	
376	export function cacheRubbings(state: LedgerState, cacheId: string): LedgerRubbing[] {
377	  return state.rubbings.filter((rubbing) => rubbing.location.kind === "cache" && rubbing.location.cacheId === cacheId);
378	}
379	
380	/** Sources of a type whose rubbing is still sealed there (locked or not). */
381	export function freeSourceCount(state: LedgerState, type: RubbingType): number {
382	  return state.rubbings.filter((rubbing) => rubbing.type === type && rubbing.location.kind === "source").length;
383	}
384	
385	/** The duel a player is in that has not settled yet, if any. */
386	export function activeDuelOf(state: LedgerState, playerId: string): LedgerDuel | undefined {
387	  return state.duels.find((duel) => duel.phase !== "settled" && duel.players.includes(playerId));
388	}
389	
390	export function reservedIn(state: LedgerState, duelId: string, playerId: string): LedgerRubbing[] {
391	  return state.rubbings.filter(
392	    (rubbing) => rubbing.location.kind === "duel" && rubbing.location.duelId === duelId && rubbing.location.playerId === playerId,
393	  );
394	}
395	
396	/**
397	 * The types the winner of a decided duel may steal (§4): held by the loser, lacked by the winner. None once the
398	 * winner has left the match, and none for a draw.
399	 */
400	export function eligibleTheftTypes(state: LedgerState, duelId: string): RubbingType[] {
401	  const duel = findDuel(state, duelId);
402	  if (!duel || duel.phase === "settled" || duel.result?.outcome !== "win") return [];
403	  const { winner, loser } = duel.result;
404	  if (winner === null || loser === null || findPlayer(state, winner)?.status === "left") return [];
405	  const winnerTypes = new Set(heldTypes(state, winner));
406	  return heldTypes(state, loser).filter((type) => !winnerTypes.has(type));
407	}
408	
409	/** §4's default theft: the eligible type with the fewest free sources, then the fixed type order. */
410	export function defaultTheftType(state: LedgerState, eligible: readonly RubbingType[]): RubbingType | null {
411	  let best: RubbingType | null = null;
412	  let bestFree = 0;
413	  for (const type of [...eligible].sort(byTypeOrder)) {
414	    const free = freeSourceCount(state, type);
415	    if (best === null || free < bestFree) {
416	      best = type;
417	      bestFree = free;
418	    }
419	  }
420	  return best;
421	}
