267	export interface AdvanceRequest {
268	  readonly tick: number;
269	}
270	
271	export interface AdvanceResult {
272	  readonly ok: boolean;
273	  readonly rejection: LedgerRejection | null;
274	  /** Duels whose choice window closed at this tick, settled with the default theft. */
275	  readonly settled: readonly LedgerDuel[];
276	  readonly transfers: readonly Transfer[];
277	  readonly cacheIds: readonly string[];
278	}
279	
280	/**
281	 * Moves the ledger's clock to `tick` and settles every duel whose choice window has closed with the default theft,
282	 * in reservation order. Call it once per world tick before that tick's requests.
283	 */
284	export function advanceLedger(state: LedgerState, request: AdvanceRequest): LedgerStep<AdvanceResult> {
285	  const bad = tickRejection(state, request.tick);
286	  if (bad) return { state, result: { ok: false, rejection: bad, settled: [], transfers: [], cacheIds: [] } };
287	  const { tick } = request;
288	  const effects = noEffects();
289	  let next = atTick(state, tick);
290	  const settled: string[] = [];
291	  for (const duel of state.duels) {
292	    if (duel.phase === "choosing" && duel.choiceDeadline !== null && tick >= duel.choiceDeadline) {
293	      next = commitWin(next, findDuel(next, duel.id)!, tick, null, effects);
294	      settled.push(duel.id);
295	    }
296	  }
297	  return {
298	    state: next,
299	    result: { ok: true, rejection: null, settled: settled.map((id) => findDuel(next, id)!), ...effects },
300	  };
301	}
