1	import { randomInt } from "node:crypto";
2	import { StateView } from "@colyseus/schema";
3	import { ErrorCode, matchMaker, Room, ServerError, type AuthContext, type Client } from "colyseus";
4	import { privateMatch } from "@pirate-sea-race/content";
5	import {
6	  createMatchOptionsSchema,
7	  DUEL_RECONNECT_SECONDS,
8	  DuelMessageType,
9	  duelReadyMessageSchema,
10	  JoinRefusal,
11	  joinMatchOptionsSchema,
12	  MATCH_CODE_REQUIRED_MESSAGE,
13	  MATCH_ROOM,
14	  MATCH_UNAVAILABLE_MESSAGE,
15	  matchFullMessage,
16	  MAX_INPUT_MESSAGES_PER_SECOND,
17	  MessageType,
18	  NO_SUCH_MATCH_MESSAGE,
19	  PROTOCOL_VERSION,
20	} from "@pirate-sea-race/protocol";
21	import {
22	  addShip,
23	  canSee,
24	  createMatchState,
25	  defaultSimulationConfig,
26	  GRAPPLE_BUTTON,
27	  isWorldStep,
28	  NEUTRAL_INPUT,
29	  NOT_DOCKED,
30	  placeShip,
31	  pointInSight,
32	  removeShip,
33	  returnShip,
34	  step,
35	  STEPS_PER_SECOND,
36	  stopShip,
37	  visibleShipIds,
38	  type MatchState,
39	  type Placement,
40	  type PlayerInput,
41	} from "@pirate-sea-race/simulation";
42	import type { PlayerIndex } from "@pirate-sea-race/simulation/duel";
43	import {
44	  createEncounterConfig,
45	  createEncounterState,
46	  duelOf,
47	  stepEncounters,
48	  type DuelReport,
49	  type EncounterEvent,
50	  type EncounterPlayerInput,
51	  type EncounterState,
52	} from "@pirate-sea-race/simulation/encounters";
53	import type { DuelAuthority } from "@pirate-sea-race/simulation/netcode";
54	import { admitSeat, authorizePrivateEntry, type AdmissionRules } from "./admission.js";
55	import { DuelMachine, type DuelDiagnostics, type DuelOutcome } from "./duelMachine.js";
56	import { InputGate } from "./inputGate.js";
57	import { generateMatchCode } from "./matchCode.js";
58	import { DuelMarkerSchema, GrappleSchema, MatchStateSchema, PlayerStatusSchema, SeaDuelSchema, ShipSchema } from "./schema.js";
59	
60	/**
61	 * The room's matchmaking listing: private matches are found by `code` (Colyseus `filterBy`). It never holds the
62	 * creator's `createToken`, so a request carrying a token matches no listing.
63	 */
64	export interface MatchMetadata {
65	  code: string;
66	  custom: boolean;
67	  /** A `filterBy` field that is never set: no listing holds a token, so no token-carrying request matches one. */
68	  createToken?: never;
69	}
70	
71	/** World updates go out at 20 Hz, the world simulation rate (§15). */
72	const PATCH_INTERVAL_MS = 1000 / 20;
73	
74	/**
75	 * World ticks a settled duel's lobby stays in its fighters' views, so both read the result before their clients return
76	 * to the sea (2 s). The winner's protection and the loser's respawn already run meanwhile.
77	 */
78	export const DUEL_RESULT_TICKS = 40;
79	
80	/** A duel at sea: the encounter rules' duel, its synced lobby and marker, and the duel machine the fighters play. */
81	interface SeaDuel {
82	  /** The encounter rules' duel id. */
83	  readonly id: string;
84	  /** The opaque key of its lobby and marker in the synced state. */
85	  readonly key: string;
86	  /** Attacker (slot 0), then the grappled player (slot 1). */
87	  readonly players: readonly [string, string];
88	  readonly lobby: SeaDuelSchema;
89	  readonly machine: DuelMachine;
90	  /** The rules' ready check ended it (a forfeit or a cancellation), so no end report goes back to them. */
91	  endedByRules: boolean;
92	  /** The end (and settlement) went to the rules. */
93	  reported: boolean;
94	  /** The world tick after which the lobby leaves the fighters' views, once settled. */
95	  removeAfterTick: number | undefined;
96	}
97	
98	/** What tests and diagnostics read about a duel at sea. */
99	export interface SeaDuelDiagnostics extends DuelDiagnostics {
100	  readonly id: string;
101	  readonly outcome: DuelOutcome | undefined;
102	  readonly players: readonly [string, string];
103	  readonly seed: number;
104	  readonly inputLog: ReturnType<DuelAuthority["inputLog"]>;
105	}
106	
107	/** Checks a create or join request for a match before matchmaking places it (see `authorizePrivateEntry`). */
108	export async function authorizeEntry(options: unknown): Promise<true> {
109	  return authorizePrivateEntry(options, MATCH_ADMISSION);
110	}
111	
112	/** A match's admission: the `match` listing, the match option schemas and the match refusal messages. */
113	const MATCH_ADMISSION: AdmissionRules = {
114	  roomName: MATCH_ROOM,
115	  createSchema: createMatchOptionsSchema,
116	  joinSchema: joinMatchOptionsSchema,
117	  noSuchMessage: NO_SUCH_MATCH_MESSAGE,
118	  codeRequiredMessage: MATCH_CODE_REQUIRED_MESSAGE,
119	  fullMessage: matchFullMessage,
120	};
121	
122	/**
123	 * One private match (§14): the only writer of its state. It runs the shared simulation on a 60 Hz fixed step,
124	 * applies validated client intent, and mirrors the simulation into the synced schema after every world step.
125	 *
126	 * Encounters (§6): each world step the room builds the tick's snapshot for `stepEncounters` (every ship, whether its
127	 * player is connected, pressed the grapple, or has a loaded arena) and applies the events: a landed grapple stops both
128	 * ships and opens a duel at sea, a `DuelMachine` (the standalone duel room's own) whose fight starts when the rules
129	 * say so; its end goes back as a report; the returns and respawns move ships. Reserved and respawning ships get
130	 * neutral input. A fighter who drops keeps the seat for DUEL_RECONNECT_SECONDS; outside a duel, leaving removes the ship.
131	 *
132	 * Visibility (§16): every client has a Colyseus StateView. After each mirror the room puts into it the client's own
133	 * ship and every ship inside that ship's sight radius, and takes out the rest, so a ship out of sight is never encoded
134	 * into that client's patches. Ships in a duel or waiting to respawn are hidden from everyone else (a duel shows as a
135	 * marker). Grapples and markers are filtered by the same sight rule; a player's status and duel go to that player
136	 * only, and a duel's frames and probes are messages to its two fighters. A fighter or a player waiting to respawn sees
137	 * no other ship. Terrain is static content every client already has, so it is not synced at all.
138	 */
139	export class MatchRoom extends Room<{ state: MatchStateSchema; metadata: MatchMetadata }> {
140	  override maxClients = privateMatch.maxPlayers;
141	  /** A flood ceiling: past it Colyseus disconnects the client. Excess input is dropped well below it, in InputGate. */
142	  override maxMessagesPerSecond = MAX_INPUT_MESSAGES_PER_SECOND * 4;
143	  override patchRate = PATCH_INTERVAL_MS;
144	  override state = new MatchStateSchema();
145	
146	  private readonly config = defaultSimulationConfig;
147	  private readonly encounterConfig = createEncounterConfig({ map: defaultSimulationConfig.map });
148	  private simulation: MatchState = createMatchState(0);
149	  private encounters: EncounterState = createEncounterState(this.encounterConfig);
150	  private readonly gates = new Map<string, InputGate>();
151	  /** Duels at sea by encounter id, from the grapple until their lobby leaves the fighters' views. */
152	  private readonly seaDuels = new Map<string, SeaDuel>();
153	  private nextDuelKey = 1;
154	  /** Reports the rules refused (none are expected), for tests. */
155	  private refusedReports = 0;
156	  /** The creator's one-time token; cleared once the creator's seat is taken. */
157	  private createToken: string | undefined;
158	
159	  static override async onAuth(_token: string, options: unknown, _context: AuthContext): Promise<true> {
160	    return authorizeEntry(options);
161	  }
162	
163	  override async onCreate(options: unknown): Promise<void> {
164	    // Only a token-carrying request creates a match. A join by code reaches here only when its match filled up or
165	    // closed after authorizeEntry admitted it (joinOrCreate then falls back to create).
166	    const parsed = createMatchOptionsSchema.safeParse(options);
167	    if (!parsed.success) throw new ServerError(ErrorCode.MATCHMAKE_INVALID_CRITERIA, MATCH_UNAVAILABLE_MESSAGE);
168	    this.createToken = parsed.data.createToken;
169	    const code = await this.allocateCode();
170	    this.simulation = createMatchState(randomInt(0, 2 ** 32));
171	    this.state.code = code;
172	    this.state.protocolVersion = PROTOCOL_VERSION;
173	    this.state.custom = privateMatch.custom;
174	    // Colyseus copied the filterBy fields of the create request, the token among them, into the listing's metadata.
175	    // Replacing the metadata drops the token before the listing is first stored.
176	    await this.setMatchmaking({ metadata: { code, custom: privateMatch.custom } });
177	
178	    this.onMessage(MessageType.Input, (client, message: unknown) => {
179	      this.gates.get(client.sessionId)?.receive(message, this.simulation.frame);
180	    });
181	    // A duel's messages reach only its machine, and only from its two fighters.
182	    this.onMessage(DuelMessageType.Input, (client, message: unknown) => this.duelOfSession(client.sessionId)?.machine.receiveInput(client.sessionId, message));
183	    this.onMessage(DuelMessageType.Probe, (client, message: unknown) => this.duelOfSession(client.sessionId)?.machine.receiveProbeReply(client.sessionId, message));
184	    this.onMessage(DuelMessageType.Ready, (client, message: unknown) => {
185	      if (duelReadyMessageSchema.safeParse(message).success) this.duelOfSession(client.sessionId)?.machine.markReady(client.sessionId);
186	    });
187	    // Unknown message types are dropped, not answered: Colyseus would otherwise disconnect the sender.
188	    this.onMessage("*", () => undefined);
189	    this.setFixedTimestep(() => this.advance(), STEPS_PER_SECOND);
190	  }
191	
192	  /**
193	   * The room's own admission check, which also covers `joinById` (no listing filter applies there): the one seat
194	   * carrying the creator's token, then only seats carrying this match's code. Throwing refuses and frees the seat.
195	   */
196	  override onJoin(client: Client, options: unknown): void {
197	    this.admit(options);
198	    this.simulation = addShip(this.config, this.simulation, client.sessionId);
199	    this.gates.set(client.sessionId, new InputGate());
200	    client.view = new StateView();
201	    this.mirror();
202	  }
203	
204	  /**
205	   * A fighter dropped without leaving (§12): the seat is kept for DUEL_RECONNECT_SECONDS while the fight goes on with
206	   * their input substituted (neutral after 250 ms); they forfeit if they stay away. Anyone else is removed as they
207	   * leave (Colyseus calls onLeave next).
208	   */
209	  override onDrop(client: Client): void {
210	    const duel = this.duelOfSession(client.sessionId);
211	    if (duel === undefined || duel.machine.outcome !== undefined) return;
212	    duel.machine.drop(client.sessionId);
213	    void this.allowReconnection(client, DUEL_RECONNECT_SECONDS).catch(() => undefined);
214	  }
215	
216	  /** The same fighter is back: the same view, and a snapshot bundle to continue the same fight from. */
217	  override onReconnect(client: Client): void {
218	    this.duelOfSession(client.sessionId)?.machine.reconnect(client.sessionId);
219	  }
220	
221	  /** A player left for good (quit, or absent past the reconnection window): a fighter forfeits; the ship goes. */
222	  override onLeave(client: Client): void {
223	    this.duelOfSession(client.sessionId)?.machine.leave(client.sessionId);
224	    this.simulation = removeShip(this.simulation, client.sessionId);
225	    this.gates.delete(client.sessionId);
226	    client.view?.dispose();
227	    client.view = undefined;
228	    this.mirror();
229	  }
230	
231	  /**
232	   * Test-only (the server's test-placement setting, off by default): puts a player's ship at rest on a navigable tile.
233	   * Visibility follows at once, as after any move.
234	   */
235	  placeShip(sessionId: string, placement: Placement): void {
236	    this.simulation = placeShip(this.config, this.simulation, sessionId, placement);
237	    this.mirror();
238	  }
239	
240	  /** The ship ids a client's view holds, for tests and diagnostics. */
241	  viewedShipIds(sessionId: string): string[] {
242	    const view = this.clients.get(sessionId)?.view;
243	    if (view === undefined) return [];
244	    return [...this.state.ships.values()].filter((ship) => view.has(ship)).map((ship) => ship.id);
245	  }
246	
247	  /** Inputs dropped per client and reason, for tests and diagnostics. */
248	  droppedInputs(sessionId: string): InputGate["dropped"] | undefined {
249	    return this.gates.get(sessionId)?.dropped;
250	  }
251	
252	  /** The encounter rules' state, for tests. */
253	  get encounterState(): EncounterState {
254	    return this.encounters;
255	  }
256	
257	  /** The simulation state, for tests. */
258	  get matchState(): MatchState {
259	    return this.simulation;
260	  }
261	
262	  /** Reports the encounter rules refused, for tests (none are expected). */
263	  get refusedDuelReports(): number {
264	    return this.refusedReports;
265	  }
266	
267	  /** The duel at sea a player is in (until its lobby leaves their view), for tests and the harness. */
268	  seaDuelDiagnostics(sessionId: string): SeaDuelDiagnostics | undefined {
269	    const duel = this.duelOfSession(sessionId);
270	    if (duel === undefined) return undefined;
271	    return { ...duel.machine.diagnostics(), id: duel.id, outcome: duel.machine.outcome, players: duel.players, seed: duel.lobby.seed, inputLog: duel.machine.authority.inputLog() };
272	  }
273	
274	  private admit(options: unknown): void {
275	    this.createToken = admitSeat(options, { code: this.state.code, createToken: this.createToken }, MATCH_ADMISSION);
276	  }
277	
278	  private advance(): void {
279	    const frame = this.simulation.frame + 1;
280	    const inputs: Record<string, PlayerInput> = {};
281	    const held = this.heldPlayers();
282	    for (const [sessionId, gate] of this.gates) {
283	      // A reserved or respawning ship ignores its player's helm (§6).
284	      if (held.has(sessionId)) inputs[sessionId] = NEUTRAL_INPUT;
285	      // A lapsed client gets no entry: its ship sails as neutral, but keeps its mooring throttle until real input.
286	      else if (!gate.lapsedAt(frame)) inputs[sessionId] = gate.inputAt(frame);
287	    }
288	    this.simulation = step(this.config, this.simulation, inputs);
289	    for (const duel of this.seaDuels.values()) duel.machine.advance();
290	    if (!isWorldStep(this.simulation.frame)) return;
291	    this.stepEncounters(frame, held);
292	    for (const gate of this.gates.values()) gate.worldStepTaken();
293	    this.mirror();
294	  }
295	
296	  /** Players whose ship is reserved for a duel (until it is settled) or waits out of the world to respawn. */
297	  private heldPlayers(): Set<string> {
298	    const held = new Set<string>();
299	    for (const duel of this.encounters.duels) for (const id of duel.players) held.add(id);
300	    for (const player of this.encounters.players) if (player.respawn !== null) held.add(player.id);
301	    return held;
302	  }
303	
304	  /** The duel at sea a session fights in (until its lobby is removed). */
305	  private duelOfSession(sessionId: string): SeaDuel | undefined {
306	    for (const duel of this.seaDuels.values()) if (duel.players.includes(sessionId)) return duel;
307	    return undefined;
308	  }
309	
310	  /** Takes a settled duel's lobby out of its fighters' views. */
311	  private closeSeaDuel(duel: SeaDuel): void {
312	    this.state.duels.delete(duel.key);
313	    this.seaDuels.delete(duel.id);
314	  }
315	
316	  /**
317	   * One world tick of §6 (`stepEncounters`): this tick's snapshot of every ship, the reports of duels that ended since
318	   * the last tick, then the events applied. The rules alone choose targets, land or miss grapples, start fights and
319	   * decide returns; the room moves ships and runs the duels.
320	   */
321	  private stepEncounters(frame: number, held: ReadonlySet<string>): void {
322	    const tick = this.simulation.worldTick;
323	    const players: EncounterPlayerInput[] = this.simulation.ships.map((ship) => {
324	      const gate = this.gates.get(ship.id);
325	      const duel = this.duelOfSession(ship.id);
326	      return {
327	        id: ship.id,
328	        mode: "ship",
329	        x: ship.x,
330	        y: ship.y,
331	        heading: ship.heading,
332	        connected: this.clients.get(ship.id) !== undefined,
333	        attack: !held.has(ship.id) && gate !== undefined && !gate.lapsedAt(frame) && (gate.inputAt(frame).buttons & GRAPPLE_BUTTON) !== 0,
334	        ready: duel?.machine.isReady(ship.id) === true,
335	        protectionEndedBy: null,
336	      };
337	    });
338	    const stepped = stepEncounters(this.encounterConfig, this.encounters, { tick, players, reports: this.duelReports(tick), matchOver: false });
339	    this.encounters = stepped.state;
340	    for (const event of stepped.events) this.apply(event);
341	    for (const duel of [...this.seaDuels.values()]) if (duel.removeAfterTick !== undefined && tick > duel.removeAfterTick) this.closeSeaDuel(duel);
342	  }
343	
344	  /**
345	   * Duels whose fight ended since the last tick: an end report (unless the rules ended it themselves) and, with no
346	   * rubbings to steal yet, the settlement on the same tick.
347	   */
348	  private duelReports(tick: number): DuelReport[] {
349	    const reports: DuelReport[] = [];
350	    for (const duel of this.seaDuels.values()) {
351	      const outcome = duel.machine.outcome;
352	      if (outcome === undefined || duel.reported) continue;
353	      duel.reported = true;
354	      if (!duel.endedByRules) {
355	        if (outcome.winner !== null) reports.push({ kind: "end", duelId: duel.id, tick, outcome: "win", winner: duel.players[outcome.winner] });
356	        // §12: both fighters forfeiting on the same frame cancels; a double KO or an exact tie is a draw.
357	        else reports.push({ kind: "end", duelId: duel.id, tick, outcome: outcome.reason === "forfeit" || outcome.reason === "cancelled" ? "cancelled" : "draw" });
358	      }
359	      reports.push({ kind: "settled", duelId: duel.id, tick });
360	    }
361	    return reports;
362	  }
363	
364	  private apply(event: EncounterEvent): void {
365	    switch (event.kind) {
366	      case "duel-reserved":
367	        this.openSeaDuel(event.duelId, event.players, event.x, event.y, event.tick);
368	        return;
369	      case "duel-started":
370	        this.seaDuels.get(event.duelId)?.machine.start();
371	        return;
372	      case "duel-forfeited":
373	      case "duel-cancelled": {
374	        const duel = this.seaDuels.get(event.duelId);
375	        if (duel === undefined) return;
376	        duel.endedByRules = true;
377	        if (event.kind === "duel-cancelled") duel.machine.end(null, "cancelled");
378	        else duel.machine.end(duel.players.indexOf(event.winner) as PlayerIndex, "forfeit");
379	        return;
380	      }
381	      case "duel-settled": {
382	        const duel = this.seaDuels.get(event.duelId);
383	        if (duel === undefined) return;
384	        duel.removeAfterTick = event.tick + DUEL_RESULT_TICKS;
385	        this.state.markers.delete(duel.key);
386	        return;
387	      }
388	      case "player-returned":
389	      case "player-respawned":
390	        if (!this.simulation.ships.some((ship) => ship.id === event.playerId)) return;
391	        this.simulation = returnShip(this.config, this.simulation, event.playerId, {
392	          x: event.x,
393	          y: event.y,
394	          dock: event.kind === "player-respawned" ? (event.dockId ?? NOT_DOCKED) : NOT_DOCKED,
395	        });
396	        return;
397	      case "report-refused":
398	        this.refusedReports++;
399	        return;
400	      default:
401	        // Attempts, protection and the loser's wait are mirrored from the rules' state.
402	        return;
403	    }
404	  }
405	
406	  /** A grapple landed: both ships stop, and their duel's countdown starts, in its lobby and marker. */
407	  private openSeaDuel(id: string, players: readonly [string, string], x: number, y: number, tick: number): void {
408	    // A winner who attacks again while the last result is still showing: that lobby goes now.
409	    for (const duel of [...this.seaDuels.values()]) if (duel.players.some((player) => players.includes(player))) this.closeSeaDuel(duel);
410	    for (const player of players) if (this.simulation.ships.some((ship) => ship.id === player)) this.simulation = stopShip(this.simulation, player);
411	    const key = `d${this.nextDuelKey++}`;
412	    const lobby = new SeaDuelSchema();
413	    lobby.code = this.state.code;
414	    lobby.practice = false;
415	    this.state.duels.set(key, lobby);
416	    const machine = new DuelMachine({
417	      lobby,
418	      seed: randomInt(0, 2 ** 32),
419	      start: "called",
420	      send: (sessionId, type, message) => this.clients.get(sessionId)?.send(type, message),
421	    });
422	    players.forEach((player, slot) => {
423	      machine.addSeat(player, slot as PlayerIndex);
424	      if (this.clients.get(player) === undefined) machine.drop(player);
425	    });
426	    machine.beginCountdown();
427	    const marker = new DuelMarkerSchema();
428	    marker.x = x;
429	    marker.y = y;
430	    marker.startTick = tick;
431	    this.state.markers.set(key, marker);
432	    this.seaDuels.set(id, { id, key, players, lobby, machine, endedByRules: false, reported: false, removeAfterTick: undefined });
433	  }
434	
435	  /** Copies the plain simulation state into the synced schema, then updates what each client may see. */
436	  private mirror(): void {
437	    this.state.frame = this.simulation.frame;
438	    this.state.worldTick = this.simulation.worldTick;
439	    this.state.players = this.simulation.ships.length;
440	    const present = new Set<string>();
441	    for (const ship of this.simulation.ships) {
442	      present.add(ship.id);
443	      let synced = this.state.ships.get(ship.id);
444	      if (synced === undefined) {
445	        synced = new ShipSchema();
446	        synced.id = ship.id;
447	        synced.slot = ship.slot;
448	        this.state.ships.set(ship.id, synced);
449	      }
450	      synced.x = ship.x;
451	      synced.y = ship.y;
452	      synced.heading = ship.heading;
453	      synced.speed = ship.speed;
454	      synced.dock = ship.dock;
455	    }
456	    for (const id of [...this.state.ships.keys()]) if (!present.has(id)) this.state.ships.delete(id);
457	    this.mirrorEncounters(present);
458	    this.updateViews();
459	  }
460	
461	  /** The rules' telegraphs and each player's status into the synced state (markers change only on events). */
462	  private mirrorEncounters(present: ReadonlySet<string>): void {
463	    const attempts = new Set<string>();
464	    for (const attempt of this.encounters.attempts) {
465	      attempts.add(attempt.attackerId);
466	      let synced = this.state.grapples.get(attempt.attackerId);
467	      if (synced === undefined) {
468	        synced = new GrappleSchema();
469	        synced.attackerId = attempt.attackerId;
470	        this.state.grapples.set(attempt.attackerId, synced);
471	      }
472	      synced.defenderId = attempt.defenderId;
473	      synced.aim = attempt.aim;
474	      synced.startTick = attempt.startTick;
475	      synced.landTick = attempt.landTick;
476	    }
477	    for (const id of [...this.state.grapples.keys()]) if (!attempts.has(id)) this.state.grapples.delete(id);
478	
479	    const records = new Map(this.encounters.players.map((player) => [player.id, player]));
480	    for (const id of present) {
481	      let status = this.state.status.get(id);
482	      if (status === undefined) {
483	        status = new PlayerStatusSchema();
484	        this.state.status.set(id, status);
485	      }
486	      const record = records.get(id);
487	      status.mode = record?.respawn != null ? "respawning" : duelOf(this.encounters, id) !== undefined ? "duel" : "sea";
488	      status.protection = record?.protection?.source ?? "";
489	      status.protectedUntil = record?.protection?.endTick ?? 0;
490	      status.cooldownUntil = record?.cooldownEndTick ?? 0;
491	      status.respawnAt = record?.respawn?.respawnTick ?? 0;
492	    }
493	    for (const id of [...this.state.status.keys()]) if (!present.has(id)) this.state.status.delete(id);
494	  }
495	
496	  /**
497	   * Each client's view (§3, §6, §16): its own ship unless it waits to respawn, the ships it can see that are not in a
498	   * duel or waiting to respawn, the grapples whose attacker it sees or that aim at it, the duel markers in its sight,
499	   * its own status and its own duel. A fighter or a player waiting to respawn sees no other ship, grapple or marker.
500	   * Nothing else is encoded for it.
501	   */
502	  private updateViews(): void {
503	    const inDuel = new Set(this.encounters.duels.flatMap((duel) => duel.players));
504	    const respawning = new Set(this.encounters.players.filter((player) => player.respawn !== null).map((player) => player.id));
505	    const ships = new Map(this.simulation.ships.map((ship) => [ship.id, ship]));
506	    for (const client of this.clients) {
507	      const view = client.view;
508	      if (view === undefined) continue;
509	      const self = client.sessionId;
510	      const viewer = ships.get(self);
511	      const away = inDuel.has(self) || respawning.has(self);
512	      const sync = (item: Parameters<typeof view.add>[0], visible: boolean) => {
513	        const shown = view.has(item);
514	        if (visible && !shown) view.add(item);
515	        else if (!visible && shown) view.remove(item);
516	      };
517	      const visible = visibleShipIds(this.config, this.simulation, self);
518	      for (const [id, ship] of this.state.ships) {
519	        sync(ship, id === self ? !respawning.has(id) : visible.has(id) && !away && !inDuel.has(id) && !respawning.has(id));
520	      }
521	      for (const [attackerId, grapple] of this.state.grapples) {
522	        const attacker = ships.get(attackerId);
523	        const aimedAt = attackerId === self || grapple.defenderId === self;
524	        sync(grapple, aimedAt || (!away && viewer !== undefined && attacker !== undefined && canSee(this.config, viewer, attacker)));
525	      }
526	      for (const marker of this.state.markers.values()) sync(marker, !away && viewer !== undefined && pointInSight(this.config, viewer, marker));
527	      for (const [id, status] of this.state.status) sync(status, id === self);
528	      for (const lobby of this.state.duels.values()) sync(lobby, lobby.seats.some((seat) => seat.sessionId === self));
529	    }
530	  }
531	
532	  private async allocateCode(): Promise<string> {
533	    for (let attempt = 0; attempt < 16; attempt++) {
534	      const code = generateMatchCode();
535	      const taken = await matchMaker.query({ name: this.roomName, code });
536	      if (taken.length === 0) return code;
537	    }
538	    throw new ServerError(JoinRefusal.BadRequest, "Could not allocate a match code");
539	  }
540	}
