96	  if (a === null || a.kind !== b.kind || a.rubbingId !== b.rubbingId) return false;
97	  return a.kind === "collect" ? b.kind === "collect" && a.sourceId === b.sourceId : b.kind === "claim" && a.cacheId === b.cacheId;
