101	  const bad = tickRejection(state, tick) ?? actorRejection(state, playerId) ?? targetRejection(state, playerId, channel);
102	  if (bad) return rejected(state, bad, playerId);
103	  if (sameTarget(findPlayer(state, playerId)!.channel, channel)) return rejected(state, "duplicate", playerId);
104	  return result(updatePlayer(atTick(state, tick), playerId, (player) => ({ ...player, channel })), playerId, "started");
