113	/**
114	 * §4: starts holding interact at an unlocked source with its rubbing still sealed there, for a type the player does
115	 * not hold. Starting replaces any other channel of the player; repeating the same start changes nothing.
116	 */
117	export function startCollect(state: LedgerState, request: StartCollectRequest): LedgerStep<ChannelResult> {
118	  const { playerId, sourceId, tick } = request;
119	  const source = typeof sourceId === "string" ? findSource(state, sourceId) : undefined;
120	  if (!source) return rejected(state, tickRejection(state, tick) ?? "unknown-source", playerId);
121	  return start(state, playerId, { kind: "collect", sourceId, rubbingId: source.rubbingId, startTick: tick, lastTick: tick, heldTicks: 0 }, tick);
122	}
