124	export interface StartCacheClaimRequest {
125	  readonly playerId: string;
126	  readonly cacheId: string;
127	  /** §12: one selected rubbing per interaction. */
128	  readonly rubbingId: string;
129	  readonly tick: number;
130	}
131	
132	/** §12: starts the interaction that claims one selected rubbing from a cache, for a player missing its type. */
133	export function startCacheClaim(state: LedgerState, request: StartCacheClaimRequest): LedgerStep<ChannelResult> {
134	  const { playerId, cacheId, rubbingId, tick } = request;
135	  if (typeof cacheId !== "string" || typeof rubbingId !== "string") return rejected(state, "invalid-request", playerId);
136	  return start(state, playerId, { kind: "claim", cacheId, rubbingId, startTick: tick, lastTick: tick, heldTicks: 0 }, tick);
137	}
138	
139	export interface ChannelTickRequest {
140	  readonly playerId: string;
141	  readonly tick: number;
142	}
143	
144	/**
145	 * The player held interact during `tick`. It must be the tick right after the channel's last one; after a gap the
146	 * hold was interrupted and counts from 0 again. On reaching the rule's ticks the channel completes: the target is
147	 * checked again, so of two players claiming the same rubbing only the first to complete gets it.
148	 */
149	export function progressChannel(state: LedgerState, request: ChannelTickRequest): LedgerStep<ChannelResult> {
150	  const { playerId, tick } = request;
151	  const bad = tickRejection(state, tick) ?? actorRejection(state, playerId);
152	  if (bad) return rejected(state, bad, playerId);
153	  const channel = findPlayer(state, playerId)!.channel;
154	  if (channel === null) return rejected(state, "no-channel", playerId);
155	  if (tick <= channel.lastTick) return rejected(state, "duplicate", playerId);
156	  const now = atTick(state, tick);
157	  if (tick > channel.lastTick + 1) {
158	    const restarted = { ...channel, startTick: tick, lastTick: tick, heldTicks: 0 };
159	    return result(updatePlayer(now, playerId, (player) => ({ ...player, channel: restarted })), playerId, "reset");
160	  }
161	  const held = { ...channel, lastTick: tick, heldTicks: channel.heldTicks + 1 };
162	  const required = channel.kind === "collect" ? state.rules.collectTicks : state.rules.cacheClaimTicks;
163	  if (held.heldTicks < required) {
164	    return result(updatePlayer(now, playerId, (player) => ({ ...player, channel: held })), playerId, "held");
165	  }
166	  const done = updatePlayer(now, playerId, (player) => ({ ...player, channel: null }));
167	  const failure = targetRejection(done, playerId, channel);
168	  if (failure) return result(done, playerId, "failed", { failure });
169	  const effects = noEffects();
170	  const next = moveRubbings(done, [{ rubbingId: channel.rubbingId, to: { kind: "player", playerId } }], effects);
171	  return result(next, playerId, channel.kind === "collect" ? "collected" : "claimed", {
172	    rubbingId: channel.rubbingId,
173	    transfers: effects.transfers,
174	  });
175	}
