181	  if (bad) return rejected(state, bad, playerId);
182	  if (findPlayer(state, playerId)!.channel === null) return rejected(state, "no-channel", playerId);
183	  return result(updatePlayer(atTick(state, tick), playerId, (player) => ({ ...player, channel: null })), playerId, "cancelled");
